INSERT INTO catalog_ingredient (recipe_version_id, position, ingredient_id, name, display_name, quantity, unit, raw_quantity, note, preparation, optional, role) VALUES ('rv_thai-yum-nua-beef-salad_v2', 12, 'scallions', 'scallions', 'scallions', 3, 'count', '3 count', NULL, 'cut into 1-inch lengths', 0, 'main');
INSERT INTO catalog_ingredient (recipe_version_id, position, ingredient_id, name, display_name, quantity, unit, raw_quantity, note, preparation, optional, role) VALUES ('rv_thai-yum-nua-beef-salad_v2', 13, 'mint', 'fresh mint', 'fresh mint leaves', 0.5, 'cup', '0.5 cup', NULL, NULL, 0, 'main');
INSERT INTO catalog_ingredient (recipe_version_id, position, ingredient_id, name, display_name, quantity, unit, raw_quantity, note, preparation, optional, role) VALUES ('rv_thai-yum-nua-beef-salad_v2', 14, 'cilantro', 'cilantro', 'cilantro leaves and tender stems', 0.5, 'cup', '0.5 cup', NULL, NULL, 0, 'main');
