INSERT INTO catalog_ingredient (recipe_version_id, position, ingredient_id, name, display_name, quantity, unit, raw_quantity, note, preparation, optional, role) VALUES ('rv_thai-yum-nua-beef-salad_v2', 16, 'jasmine-rice', 'jasmine rice', 'jasmine rice', 1.5, 'cup', '1.5 cup', NULL, 'rinsed', 0, 'main');
