INSERT INTO catalog_ingredient (recipe_version_id, position, ingredient_id, name, display_name, quantity, unit, raw_quantity, note, preparation, optional, role) VALUES ('rv_white-bean-kale-soup_v3', 1, NULL, 'neutral oil', 'neutral oil', 1, 'tbsp', '1 tbsp', NULL, NULL, 0, NULL);
INSERT INTO catalog_ingredient (recipe_version_id, position, ingredient_id, name, display_name, quantity, unit, raw_quantity, note, preparation, optional, role) VALUES ('rv_white-bean-kale-soup_v3', 2, NULL, 'garlic', 'garlic', 2, 'clove', '2 clove', 'Minced.', NULL, 0, NULL);
INSERT INTO catalog_ingredient (recipe_version_id, position, ingredient_id, name, display_name, quantity, unit, raw_quantity, note, preparation, optional, role) VALUES ('rv_white-bean-kale-soup_v3', 3, NULL, 'cannellini beans', 'cannellini beans', 2, 'can', '2 can', '15 oz cans, drained and rinsed.', NULL, 0, NULL);
INSERT INTO catalog_ingredient (recipe_version_id, position, ingredient_id, name, display_name, quantity, unit, raw_quantity, note, preparation, optional, role) VALUES ('rv_white-bean-kale-soup_v3', 4, NULL, 'vegetable broth', 'vegetable broth', 6, 'cup', '6 cup', 'Check the carton. Wheat or soy on the label would be an allergen this package does not claim.', NULL, 0, NULL);
INSERT INTO catalog_ingredient (recipe_version_id, position, ingredient_id, name, display_name, quantity, unit, raw_quantity, note, preparation, optional, role) VALUES ('rv_white-bean-kale-soup_v3', 5, NULL, 'diced tomatoes', 'diced tomatoes', 1, 'can', '1 can', '14.5 oz, with their liquid.', NULL, 0, NULL);
INSERT INTO catalog_ingredient (recipe_version_id, position, ingredient_id, name, display_name, quantity, unit, raw_quantity, note, preparation, optional, role) VALUES ('rv_white-bean-kale-soup_v3', 6, NULL, 'kale', 'kale', 4, 'cup', '4 cup', 'Chopped.', NULL, 0, NULL);
INSERT INTO catalog_ingredient (recipe_version_id, position, ingredient_id, name, display_name, quantity, unit, raw_quantity, note, preparation, optional, role) VALUES ('rv_white-bean-kale-soup_v3', 7, NULL, 'Diamond Crystal kosher salt', 'Diamond Crystal kosher salt', 4, 'g', '4 g', 'Stirred in at the end. If the broth is already salty, start with 2 g. 4 g Diamond Crystal kosher salt (1.5 tsp). The same weight is 0.75 tsp Morton coarse kosher salt or 0.75 tsp table salt. UC ANR publication 390575 (November 2023): Diamond Crystal kosher salt 2.8 g per teaspoon, Morton coarse kosher salt 4.8 g per teaspoon, table salt 6 g per teaspoon.', NULL, 0, NULL);
INSERT INTO catalog_ingredient (recipe_version_id, position, ingredient_id, name, display_name, quantity, unit, raw_quantity, note, preparation, optional, role) VALUES ('rv_white-bean-kale-soup_v3', 8, NULL, 'black pepper', 'black pepper', 0.25, 'tsp', '0.25 tsp', NULL, NULL, 0, NULL);
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_black-bean-quesadillas_v3', 1, 'Season the beans', 'Mash the black beans with the ground cumin, garlic, lime juice, and Diamond Crystal kosher salt. Taste the mash and add a pinch more salt only if it still tastes flat next to the cheese.', '["black beans","ground cumin","garlic","lime","Diamond Crystal kosher salt"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_black-bean-quesadillas_v3', 2, 'Fill and crisp', 'Spread the beans and half the shredded cheese on the flour tortillas, top with the rest of the cheese, and fold. Cook in the neutral oil over medium heat 2 to 3 minutes per side, until golden.', '["black beans","shredded cheese","flour tortillas","neutral oil"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_black-bean-quesadillas_v3', 3, 'Serve', 'Cut into wedges and serve with the salsa.', '["salsa","flour tortillas"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_cashew-pesto-pasta_v3', 1, 'Toast the cashews', 'Toast the raw cashews in a dry skillet over medium heat until golden, 4 to 5 minutes. Reserve 2 tbsp, chopped, for the top.', '["raw cashews"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_cashew-pesto-pasta_v3', 2, 'Blend the pesto', 'Blend the remaining cashews with the garlic, lemon zest, 2 tbsp lemon juice, nutritional yeast, 2.5 g of the Diamond Crystal kosher salt, 3 tbsp extra-virgin olive oil, and the black pepper until thick. Add the basil and pulse until green and still a little coarse. Taste the pesto, which is meant to be eaten without further cooking, and add the remaining lemon juice if it tastes dull. No cheese: this pesto is dairy-free, and nutritional yeast plus salt replace the savoriness cheese would have brought.', '["raw cashews","garlic","lemon","nutritional yeast","Diamond Crystal kosher salt","extra-virgin olive oil","black pepper","basil"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_cashew-pesto-pasta_v3', 3, 'Boil the pasta', 'Bring the water to a boil with 28 g of the Diamond Crystal kosher salt (about 1% by weight, 28 g per 3 qt). Boil the short pasta until al dente. Reserve 1 cup of the salted pasta water, then drain.', '["water","Diamond Crystal kosher salt","short pasta"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_cashew-pesto-pasta_v3', 4, 'Season the tomatoes', 'Toss the cherry tomatoes with 1 tsp of the extra-virgin olive oil and the remaining 0.5 g Diamond Crystal kosher salt.', '["cherry tomatoes","extra-virgin olive oil","Diamond Crystal kosher salt"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_cashew-pesto-pasta_v3', 5, 'Toss and finish', 'Off the heat, toss the pasta with the pesto and 1/4 to 1/2 cup of the salted pasta water until the sauce looks glossy. Taste a noodle and add salt or lemon only if that bite needs it. Finish with the rest of the olive oil, the toasted cashews, and a few basil leaves.', '["short pasta","cherry tomatoes","raw cashews","basil","lemon","extra-virgin olive oil"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_chipotle-lime-black-bean-bowls_v3', 1, 'Cook the quinoa', 'Rinse the quinoa. Simmer it covered in the water with 2 g of the Diamond Crystal kosher salt, about 15 minutes, until the grains are tender and the water is absorbed (about 0.6% salt, because that water stays in the grain). Rest covered 5 minutes, then fluff.', '["quinoa","water","Diamond Crystal kosher salt"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_chipotle-lime-black-bean-bowls_v3', 2, 'Simmer the beans', 'Warm the neutral oil, stir in the ground cumin and the chipotle in adobo for 30 seconds, then add the black beans, 3 g Diamond Crystal kosher salt, and the juice of 1 lime. Simmer 10 minutes, until the beans are hot and coated. Taste a bean, which is fully cooked, and add a pinch more salt only if the chipotle still tastes flat. Cut the second lime into wedges.', '["neutral oil","ground cumin","chipotle in adobo","black beans","Diamond Crystal kosher salt","lime"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_chipotle-lime-black-bean-bowls_v3', 3, 'Assemble', 'Toss the corn with the remaining 1 g Diamond Crystal kosher salt. Layer quinoa, beans, and corn. Add the lime wedges.', '["corn","Diamond Crystal kosher salt","quinoa","black beans","lime"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_ethiopian-beef-tibs_v2', 1, 'Cube and season the beef', 'Pat the beef dry. Cut into 3/4-inch cubes. Toss with 3/4 tsp kosher salt, black pepper, and 1 tbsp of the berbere. Rest 10 minutes at room temperature while you slice the onions and mince garlic and ginger. Dice the tomato. Chop the cilantro. Juice the lime. Confirm berbere is an Ethiopian blend, not plain chili powder.', '["beef-sirloin","kosher-salt","black-pepper","berbere","yellow-onion","garlic","fresh-ginger","tomato","fresh-cilantro","lime"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_ethiopian-beef-tibs_v2', 2, 'Sear the beef', 'Heat 2 tbsp of the neutral oil in a 12-inch skillet over medium-high until shimmering. Add the beef in a single layer (two batches if needed). Sear undisturbed until deeply browned on the first side, about 2 to 3 minutes. Toss and sear until browned on most sides but still pink inside, about 2 minutes more. Transfer beef to a plate. Do not cook through yet.', '["neutral-oil","beef-sirloin"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_ethiopian-beef-tibs_v2', 3, 'Cook the onion berbere base', 'Add the remaining 1 tbsp oil to the same skillet over medium heat. Add the sliced onions and 1/2 tsp kosher salt. Cook, stirring, until onions soften and pick up browned bits, about 6 to 8 minutes. Add garlic, ginger, remaining 1 tbsp berbere, smoked paprika, and optional cardamom. Cook until fragrant and brick-red, about 1 minute. Stir in the diced tomato. Cook until the tomato softens into the onions, about 2 to 3 minutes.', '["neutral-oil","yellow-onion","kosher-salt","garlic","fresh-ginger","berbere","smoked-paprika","ground-cardamom","tomato"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_ethiopian-beef-tibs_v2', 4, 'Finish tibs and plate', 'Return the seared beef and any plate juices to the skillet. Toss over medium-high heat until the beef is coated and cooked to 145 F in the center, about 3 to 4 minutes, then rest 3 minutes off the heat. Optional traditional preparation: medium cubes, about 135 F to 140 F. That lower temperature does not meet the USDA/FDA recommendation and carries higher risk, especially for young children, pregnant people, older adults, and anyone immunocompromised. Do not stew into a long braise — tibs stay skillet-quick. Off heat, stir in lime juice and cilantro. Serve over cooked rice or sautéed greens. Injera on the side is optional if you have it; it is not required. No yogurt sauce. No nuts. kitchen_tested is false.', '["beef-sirloin","lime","fresh-cilantro","cooked-rice-or-greens"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_ginger-scallion-fish-packets_v3', 1, 'Start the rice', 'Rinse the long-grain white rice. Combine it with the water and the Diamond Crystal kosher salt. Bring to a boil, cover, and simmer 18 minutes, until the rice is tender and the water is absorbed. The 4 g is about 0.5% of the 3 cups because that water stays in the rice.', '["long-grain white rice","water","Diamond Crystal kosher salt"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_ginger-scallion-fish-packets_v3', 2, 'Pack the packets', 'Heat the oven to 400 F. On each of 4 foil sheets put 1 white fish fillet and half a head of bok choy. Divide the ginger, scallions, soy sauce, and the water for packets across the four packets. Seal the foil.', '["white fish fillets","bok choy","ginger","scallions","soy sauce","water for packets"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_ginger-scallion-fish-packets_v3', 3, 'Bake', 'Bake at 400 F for 18 to 20 minutes, until the fish flakes, is opaque in the center, and reads 145 F, and the bok choy is tender.', '["white fish fillets","bok choy"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_ginger-scallion-fish-packets_v3', 4, 'Serve', 'Open the foil carefully. Spoon the packet juices over the fish and the rice. Those juices are the sauce.', '["long-grain white rice","white fish fillets","soy sauce"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_gochujang-grilled-flank-steak_v2', 1, 'Mix the marinade', 'In a bowl, stir the gochujang, soy sauce, 1 tbsp of the rice vinegar, 3 tsp of the toasted sesame oil, brown sugar, garlic, fresh ginger, and black pepper into a thick paste. Mince 2 of the scallions and stir them in. This marinade cooks on the meat. Do not serve any of it raw.', '["gochujang","soy-sauce","rice-vinegar","toasted-sesame-oil","brown-sugar","garlic","fresh-ginger","black-pepper","scallions"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_gochujang-grilled-flank-steak_v2', 2, 'Marinate the steak', 'Pat the flank steak dry and coat both sides with all of the marinade. Leave it at room temperature for 15 minutes. Do not add kosher salt to the steak; the soy sauce is already salty.', '["flank-steak"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_gochujang-grilled-flank-steak_v2', 3, 'Make the salad', 'While the steak marinates, thinly slice the cucumber and slice the remaining 2 scallions. Toss them with the remaining 1 tbsp rice vinegar, the remaining 1 tsp toasted sesame oil, the kosher salt, and the sesame seeds.', '["cucumber","scallions","rice-vinegar","toasted-sesame-oil","kosher-salt","sesame-seeds"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_gochujang-grilled-flank-steak_v2', 4, 'Heat the grill', 'After the 15 minutes, heat a gas or charcoal grill for direct high heat, about 450–500°F. Give it about 10 minutes. When the grates are hot, brush them with the canola oil. This timed method does not overlap preheat with the marinade.', '["canola-oil"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_gochujang-grilled-flank-steak_v2', 5, 'Grill', 'Lay the flank steak on the oiled grates. Close the lid on a gas grill, or grill over direct coals with the vents open. Cook 5 to 6 minutes per side. It is done at 145 F in the thickest center. Optional traditional preparation: medium-rare, 130 F to 135 F. That lower temperature does not meet the USDA/FDA recommendation and carries higher risk, especially for young children, pregnant people, older adults, and anyone immunocompromised. Do not press the steak. If the piece is thicker than 1 inch, add about 1 minute per side and trust the thermometer.', '["flank-steak"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_gochujang-grilled-flank-steak_v2', 6, 'Rest and slice', 'Move the flank steak to a board and rest it for 5 minutes. Slice it thin, against the grain: cut across the long muscle lines, not parallel to them. Discard any marinade left in the bowl.', '["flank-steak"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_gochujang-grilled-flank-steak_v2', 7, 'Plate', 'Serve the slices with the cucumber and scallions beside them. This plate has no rice and no extra sauce.', '["cucumber","scallions"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_grilled-swordfish-olive-caper_v2', 1, 'Mix the relish', 'Chop the pitted green olives. Rinse and drain the capers. Mince the anchovy fillets and the garlic. Zest the lemon and squeeze in all of the juice. Chop the fresh parsley. Stir them with 3 tbsp of the olive oil, 1/4 tsp of the kosher salt, and the red pepper flakes. This olive-caper relish is the only sauce. It is not cooked, and it is not a marinade rubbed on the fish before the grill.', '["pitted-green-olives","capers","anchovy-fillets","garlic","lemon","fresh-parsley","olive-oil","kosher-salt","red-pepper-flakes"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_grilled-swordfish-olive-caper_v2', 2, 'Heat the grill', 'Heat a gas or charcoal grill for direct high heat, about 450-500 F, for about 10 minutes. Brush the grates with 1 tbsp of the olive oil. This clock does not overlap the preheat with the relish.', '["olive-oil"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_grilled-swordfish-olive-caper_v2', 3, 'Season', 'Pat the swordfish steak dry. Season both sides with 3/4 tsp of the kosher salt and the black pepper. Toss the fennel bulb wedges with 1 tbsp of the olive oil and the remaining 1/4 tsp kosher salt.', '["swordfish-steak","kosher-salt","black-pepper","fennel-bulb","olive-oil"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_grilled-swordfish-olive-caper_v2', 4, 'Grill the fennel', 'Lay the fennel bulb wedges on the oiled grates. Grill about 3 minutes per side, until the cut faces are browned and a knife meets slight resistance. Move them to a plate.', '["fennel-bulb"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_grilled-swordfish-olive-caper_v2', 5, 'Grill the swordfish', 'Lay the swordfish steak on the grates. Cook 5 minutes on the first side without moving it, then flip. Cook 4 to 5 minutes on the second side. Pull it at 145 F in the center. Do not press the fish. If a steak is thicker than 1 1/4 inches, add about 1 minute per side and trust the thermometer. Optional traditional preparation: pulling at 130 F to 135 F, about 4 minutes then 3 to 4 minutes. That lower temperature does not meet the USDA/FDA recommendation and carries higher risk, especially for young children, pregnant people, older adults, and anyone immunocompromised.', '["swordfish-steak"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_grilled-swordfish-olive-caper_v2', 6, 'Rest and plate', 'Rest the swordfish steak 3 minutes. Serve each steak with fennel bulb wedges and spoon the relish on the fish. No rice, no extra lemon wedge, and no second sauce.', '["swordfish-steak","fennel-bulb","pitted-green-olives","capers"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_harissa-roasted-carrots-feta_v3', 1, 'Roast', 'Heat the oven to 425 F. Toss the carrots with the harissa paste, neutral oil, and 4 g of the Diamond Crystal kosher salt. Roast 30 minutes, until tender and browned at the edges.', '["carrots","harissa paste","neutral oil","Diamond Crystal kosher salt"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_harissa-roasted-carrots-feta_v3', 2, 'Couscous', 'Stir the couscous and the remaining 2 g Diamond Crystal kosher salt into the boiling water. Cover 5 minutes off the heat, then fluff. The 2 g in 1 cup is about 0.8% and the water is absorbed.', '["couscous","Diamond Crystal kosher salt","water"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_harissa-roasted-carrots-feta_v3', 3, 'Finish', 'Squeeze the lemon over the carrots. Top with the feta and the mint. Serve over the couscous.', '["lemon","feta","mint","carrots","couscous"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_lemon-garlic-shrimp-pasta_v3', 1, 'Boil the pasta', 'Bring the water to a boil with 28 g of the Diamond Crystal kosher salt (about 1% by weight, 28 g per 3 qt). Boil the linguine until al dente. Reserve 1/2 cup pasta water, then drain.', '["water","Diamond Crystal kosher salt","linguine"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_lemon-garlic-shrimp-pasta_v3', 2, 'Sear the shrimp', 'Pat the large shrimp dry and season with the remaining 3 g Diamond Crystal kosher salt and the black pepper. Sear them in the olive oil with the garlic over medium-high heat, about 2 minutes per side, until pink, opaque, and 145 F in the thickest piece.', '["large shrimp","Diamond Crystal kosher salt","black pepper","olive oil","garlic"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_lemon-garlic-shrimp-pasta_v3', 3, 'Finish', 'Off the heat, toss the linguine with the shrimp, the lemon zest and juice, the parsley, and a splash of pasta water. Taste a noodle and a shrimp, both cooked, and add lemon or a pinch of salt only if the bowl needs it. Serve with the remaining lemon wedges.', '["linguine","large shrimp","lemon","parsley"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_linguine-with-clams_v2', 1, 'Scrub and boil', 'Scrub the clams. Slice the garlic, chop the parsley, and juice the lemon. Bring 4 qt of water to a boil with the Diamond Crystal kosher salt (38 g, about 1% by weight). The water should be boiling by the end of this 15-minute prep.', '["littleneck-clams","garlic","parsley","lemon","kosher-salt"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_linguine-with-clams_v2', 2, 'Pasta and clams', 'Boil the linguine until it is almost tender, about 10 minutes. Meanwhile warm the olive oil, garlic, and red pepper flakes in a skillet over medium until the garlic is fragrant, about 1 minute. Add the wine and the clams, cover, and cook until the clams open, about 6 to 8 minutes. Discard any that stay shut.', '["linguine","olive-oil","garlic","red-pepper-flakes","white-wine","littleneck-clams"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_linguine-with-clams_v2', 3, 'Toss', 'Drain the pasta, reserving 1/2 cup pasta water. Toss the pasta with the clams, their liquor, the parsley, lemon juice, and pepper. Loosen with pasta water if it looks dry. Taste a noodle with a clam, both cooked, and add salt only if the brine did not already season the bowl.', '["linguine","littleneck-clams","parsley","lemon","black-pepper"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_malaysian-curry-laksa_v2', 1, 'Soak and blend the paste', 'Pour 1 cup boiling water over the dried chiles and soak 15 minutes; drain and discard the soaking liquid. Meanwhile peel the shallots and garlic and chop the ginger and lemongrass. Blend the chiles, shallots, garlic, ginger, lemongrass, turmeric, coriander, and shrimp paste with 1 tbsp of the oil into a smooth paste. Cut the cucumber, pick the mint, and cut the limes. Put 16 cups (4 quarts) water on to boil for the noodles in the 6- to 8-quart pot.', '["soak-water","dried-chiles","shallots","garlic","ginger","lemongrass","turmeric","ground-coriander","shrimp-paste","neutral-oil","cucumber","mint","limes","noodle-water"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_malaysian-curry-laksa_v2', 2, 'Cook the paste', 'Heat the remaining 2 tbsp oil in the 6-quart pot over medium. Cook the paste, stirring constantly, until it darkens, smells sweet, and the oil separates, 8 minutes.', '["neutral-oil","dried-chiles"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_malaysian-curry-laksa_v2', 3, 'Simmer the broth', 'Whisk in the coconut milk and stock, add the fish sauce, brown sugar, and salt, and simmer on medium-low 12 minutes.', '["coconut-milk","chicken-stock","fish-sauce","brown-sugar","kosher-salt"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_malaysian-curry-laksa_v2', 4, 'Cook the noodles', 'While the broth simmers, cook the vermicelli in the 4 quarts of boiling water until tender, 3 to 4 minutes, and drain. Runs inside step 3 (overlap stated).', '["rice-vermicelli","noodle-water"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_malaysian-curry-laksa_v2', 5, 'Poach the shrimp', 'Add the shrimp to the broth and simmer gently until pink, opaque, and firm, 3 to 4 minutes. Optional traditional preparation: shrimp that are still translucent in the center, about 120 F to 125 F. That lower temperature does not meet the USDA/FDA recommendation and carries higher risk, especially for young children, pregnant people, older adults, and anyone immunocompromised.', '["shrimp"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_malaysian-curry-laksa_v2', 6, 'Serve', 'Divide the noodles and bean sprouts among deep bowls, ladle in the broth and shrimp, and top with cucumber, mint, and lime wedges.', '["rice-vermicelli","bean-sprouts","shrimp","cucumber","mint","limes"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_maple-mustard-glazed-salmon_v3', 1, 'Heat the oven and season', 'Heat the oven to 425 F with a rack in the upper third. Pat the salmon fillets dry. Season them with 5 g of the Diamond Crystal kosher salt and most of the black pepper.', '["salmon fillets","Diamond Crystal kosher salt","black pepper"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_maple-mustard-glazed-salmon_v3', 2, 'Season the asparagus', 'Toss the asparagus with 1 tbsp of the olive oil, 2 g of the Diamond Crystal kosher salt, and the rest of the black pepper. Do not brush the glaze onto the asparagus, because the glaze is for the salmon and would make the stalks sticky instead of roasted.', '["asparagus","olive oil","Diamond Crystal kosher salt","black pepper"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_maple-mustard-glazed-salmon_v3', 3, 'Make the glaze', 'Whisk the Dijon mustard, maple syrup, grated garlic, the lemon zest, the remaining 1 tbsp olive oil, and the remaining 1 g Diamond Crystal kosher salt. Set aside 2 tbsp of this glaze for the finish.', '["Dijon mustard","maple syrup","garlic","lemon","olive oil","Diamond Crystal kosher salt"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_maple-mustard-glazed-salmon_v3', 4, 'Roast and broil', 'Roast the salmon fillets and the asparagus on a sheet pan at 425 F until the thickest part of the salmon is 145 F, opaque in the center, and flakes, about 8 to 12 minutes. Broil 1 to 3 minutes, watching, until the glaze spots amber. Rest 3 minutes.', '["salmon fillets","asparagus"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_maple-mustard-glazed-salmon_v3', 5, 'Finish', 'Whisk 1 tbsp lemon juice into the reserved glaze and spoon it over the salmon. Scatter the fresh dill and serve the remaining lemon as wedges.', '["lemon","fresh dill","salmon fillets"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_moroccan-chickpea-skillet_v3', 1, 'Steam the couscous', 'Put the couscous and 2 g of the Diamond Crystal kosher salt in a bowl. Pour over 1.5 cups boiling water. Cover 5 minutes, then fluff. The 2 g in 1.5 cups is about 0.5% and the water is absorbed.', '["couscous","Diamond Crystal kosher salt","water"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_moroccan-chickpea-skillet_v3', 2, 'Spice the chickpeas', 'Warm the neutral oil in a skillet over medium heat. Stir in the garlic and the ras el hanout and cook 1 minute. Add the chickpeas and 1/4 cup water. Cook 5 minutes, until the chickpeas are glossy.', '["neutral oil","garlic","ras el hanout","chickpeas","water"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_moroccan-chickpea-skillet_v3', 3, 'Finish', 'Stir in the preserved lemon and the spinach. Cook 1 to 2 minutes, until the spinach wilts. Taste a chickpea. Preserved lemon is already salty and brands vary, so add up to the remaining 2 g Diamond Crystal kosher salt only if the skillet tastes flat.', '["preserved lemon","spinach","chickpeas","Diamond Crystal kosher salt"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_moroccan-chickpea-skillet_v3', 4, 'Serve', 'Serve the skillet over the couscous and top with the parsley.', '["couscous","parsley","chickpeas"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_mushroom-walnut-bolognese_v3', 1, 'Brown', 'Cook the cremini mushrooms and the walnuts in the olive oil with 4 g of the Diamond Crystal kosher salt until the mushrooms are deeply browned. Work in batches if the pan is crowded.', '["cremini mushrooms","walnuts","olive oil","Diamond Crystal kosher salt"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_mushroom-walnut-bolognese_v3', 2, 'Simmer and boil', 'Add the garlic, crushed tomatoes, and black pepper. Simmer 20 minutes. Meanwhile bring the water to a boil with the remaining 28 g Diamond Crystal kosher salt (about 1% by weight, 28 g per 3 qt) and boil the spaghetti until al dente. Reserve 1/2 cup pasta water.', '["garlic","crushed tomatoes","black pepper","water","Diamond Crystal kosher salt","spaghetti"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_mushroom-walnut-bolognese_v3', 3, 'Toss', 'Taste the sauce and add salt only if it still tastes flat. Toss the spaghetti with the sauce, loosening it with pasta water if it looks thick.', '["spaghetti","cremini mushrooms"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_nigerian-beef-suya-skewers_v2', 1, 'Make yaji and prep', 'Grind the peanuts in a spice grinder or mini processor to a coarse powder (pulse; stop before it turns to butter). Mix with the ginger, garlic powder, onion powder, paprika, cayenne, and 1 tsp salt. Toss the beef with the oil and 3/4 of the yaji and thread onto 8 metal skewers. Slice the tomatoes and onion, shred the cabbage, and cut the lime.', '["roasted-peanuts","ground-ginger","garlic-powder","onion-powder","smoked-paprika","cayenne","kosher-salt","beef-sirloin","neutral-oil","tomatoes","red-onion","cabbage","lime"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_nigerian-beef-suya-skewers_v2', 2, 'Cook the rice', 'Rinse the rice until the rinse runs clear. Bring it to a boil with the 2.25 cups water and 1/2 tsp salt in the saucepan, cover, simmer on low 15 minutes, then rest off heat 10 minutes.', '["jasmine-rice","rice-water","kosher-salt"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_nigerian-beef-suya-skewers_v2', 3, 'Preheat the grill', 'While the rice simmers, preheat the grill or grill pan to high for 10 minutes and oil the grates (overlap stated).', '["neutral-oil"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_nigerian-beef-suya-skewers_v2', 4, 'Grill the suya', 'Grill the skewers over high heat, turning once, until charred at the edges and 145 F in the thicker pieces, 4 to 5 minutes per side, then rest 3 minutes. Sprinkle with the remaining yaji. Optional traditional preparation: at least medium, about 140 F. That lower temperature does not meet the USDA/FDA recommendation and carries higher risk, especially for young children, pregnant people, older adults, and anyone immunocompromised.', '["beef-sirloin","roasted-peanuts"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_nigerian-beef-suya-skewers_v2', 5, 'Serve', 'Serve the skewers over the rice with the tomato, onion, cabbage, and lime wedges.', '["beef-sirloin","jasmine-rice","tomatoes","red-onion","cabbage","lime"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_pan-seared-halibut-lemon-butter-corn_v2', 1, 'Prep', 'Pat the halibut very dry and season with 1 tsp salt and the pepper. Halve the tomatoes, slice the scallions, smash the garlic, and juice half the lemon.', '["halibut","kosher-salt","black-pepper","cherry-tomatoes","scallions","garlic","lemon"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_pan-seared-halibut-lemon-butter-corn_v2', 2, 'Saute the corn', 'Heat the olive oil in the 10-inch skillet over medium-high. Cook the corn and scallions until lightly browned, 4 minutes, add the tomatoes and 1/2 tsp salt for 2 minutes, and move off the heat.', '["olive-oil","corn","scallions","cherry-tomatoes","kosher-salt"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_pan-seared-halibut-lemon-butter-corn_v2', 3, 'Sear the halibut', 'Heat the neutral oil in the 12-inch skillet over medium-high until shimmering. Sear the fillets without moving until golden, 4 minutes, then flip.', '["neutral-oil","halibut"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_pan-seared-halibut-lemon-butter-corn_v2', 4, 'Baste with lemon butter', 'Lower to medium, add the butter and garlic, and spoon the foaming butter over the fish until opaque at the center and 145 F, 4 minutes. Add the lemon juice. Optional traditional preparation: just opaque at 130 F to 135 F after about 3 minutes. That lower temperature does not meet the USDA/FDA recommendation and carries higher risk, especially for young children, pregnant people, older adults, and anyone immunocompromised.', '["butter","garlic","halibut","lemon"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_pan-seared-halibut-lemon-butter-corn_v2', 5, 'Serve', 'Spoon the corn onto plates, top with the halibut and pan butter, and scatter with basil. Serve with lemon wedges.', '["corn","halibut","basil","lemon"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_roasted-cauliflower-shawarma-plate_v3', 1, 'Roast the cauliflower', 'Heat the oven to 425 F. Toss the cauliflower with the neutral oil, the shawarma spice blend, and 4 g of the Diamond Crystal kosher salt. Roast 25 minutes, until the edges char and a stem is tender.', '["cauliflower","neutral oil","shawarma spice blend","Diamond Crystal kosher salt"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_roasted-cauliflower-shawarma-plate_v3', 2, 'Make the sauce', 'Whisk the tahini with the grated garlic, the juice of 1/2 lemon, the water, and 2 g Diamond Crystal kosher salt until it drizzles.', '["tahini","garlic","lemon","water","Diamond Crystal kosher salt"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_roasted-cauliflower-shawarma-plate_v3', 3, 'Warm the pita and plate', 'Dice the cucumber and toss it with the remaining lemon juice and the remaining 1 g Diamond Crystal kosher salt. Warm the pita in foil for the last 3 minutes of the roast. Serve cauliflower, cucumber, sauce, and pita. Feta is not in this dish because this package does not claim a dairy-free or dairy contract for the spice blend, and feta would add a dairy allergen the recipe does not list.', '["cucumber","lemon","Diamond Crystal kosher salt","pita","cauliflower","tahini"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_roasted-whole-branzino-salmoriglio_v2', 1, 'Preheat and prep', 'Turn the oven on to 450 F to preheat with a rack in the middle. Slice the potatoes and onion. Slice 1 lemon and juice and zest the other 2. Slice 2 cloves garlic and grate 2. Pat the fish dry inside and out and score each side 3 times.', '["yukon-potatoes","red-onion","lemons","garlic","branzino"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_roasted-whole-branzino-salmoriglio_v2', 2, 'Roast the potatoes', 'Toss the potatoes and onion with 3 tbsp olive oil, 1 1/4 tsp salt, and the pepper, spread on the sheet pan, and roast in the preheated 450 F oven 20 minutes, until starting to brown.', '["yukon-potatoes","red-onion","olive-oil","kosher-salt","black-pepper"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_roasted-whole-branzino-salmoriglio_v2', 3, 'Season the fish and make the salmoriglio', 'While the potatoes roast, season the fish inside and out with 1 1/2 tsp salt, stuff each cavity with lemon slices, sliced garlic, and 2 oregano sprigs, and rub with 2 tbsp olive oil. Whisk the lemon juice and zest, grated garlic, chopped oregano, parsley, chile flakes, 1/4 tsp salt, and 1/3 cup olive oil. Runs inside step 2 (overlap stated).', '["branzino","kosher-salt","lemons","garlic","fresh-oregano","olive-oil","parsley","chile-flakes"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_roasted-whole-branzino-salmoriglio_v2', 4, 'Roast the fish', 'Flip the potatoes, lay the fish on top, and roast 18 to 22 minutes, until the flesh is opaque at the backbone and 145 F at the thickest point and the potatoes are golden. Optional traditional preparation: 135 F to 140 F at the thickest point. That lower temperature does not meet the USDA/FDA recommendation and carries higher risk, especially for young children, pregnant people, older adults, and anyone immunocompromised.', '["yukon-potatoes","branzino"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_roasted-whole-branzino-salmoriglio_v2', 5, 'Fillet and serve', 'Run a knife along the backbone, lift off the top fillets, pull out the spine, and lift the bottom fillets off the skin. Serve with the potatoes and spoon the salmoriglio over everything.', '["branzino","yukon-potatoes","lemons"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_salade-nicoise-seared-tuna_v2', 1, 'Start the water and prep', 'Fill a 5- to 6-quart pot with 3 quarts water, add 1 tbsp of the kosher salt, cover, and bring to a boil over high heat (about 10 minutes; this overlaps the prep). Halve the potatoes, trim the green beans, halve the cherry tomatoes, separate, wash, and dry the lettuce leaves, mince the shallot, grate the garlic, chop the parsley, and drain the capers. Set out a large bowl of ice water. Pat the tuna dry and leave it on a plate while you work. About 12 minutes.', '["kosher-salt","baby-potatoes","green-beans","cherry-tomatoes","butter-lettuce","shallot","garlic","flat-leaf-parsley","capers","ahi-tuna-steaks"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_salade-nicoise-seared-tuna_v2', 2, 'Shake the Dijon-shallot vinaigrette', 'In a jar, combine the minced shallot, 3 tbsp red wine vinegar, and 1/2 tsp kosher salt; let it sit while you measure the rest so the shallot mellows. Add the 1 tbsp Dijon, the grated garlic, 1/4 tsp cracked pepper, and the 1/2 cup extra-virgin olive oil. Close and shake hard until creamy and emulsified. The dressing is oil, vinegar, and mustard only: no butter, cream, yogurt, or cheese. About 3 minutes.', '["shallot","red-wine-vinegar","kosher-salt","dijon-mustard","garlic","black-pepper","extra-virgin-olive-oil"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_salade-nicoise-seared-tuna_v2', 3, 'Boil the potatoes and jammy eggs in one pot', 'Add the potatoes to the boiling water and keep it at a steady boil. After 6 minutes, gently lower the cold eggs into the same pot with a slotted spoon. Boil 7 more minutes, then move the eggs to the ice water. Test a potato: a knife should slide in with no resistance. Lift the potatoes out with the slotted spoon into a wide bowl and toss them while hot with 2 tbsp of the vinaigrette so they absorb it. Keep the water boiling. About 13 minutes.', '["baby-potatoes","eggs","extra-virgin-olive-oil","red-wine-vinegar"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_salade-nicoise-seared-tuna_v2', 4, 'Blanch the green beans; heat the skillet', 'Drop the green beans into the same boiling water and cook 2 1/2 to 3 minutes, until bright green and crisp-tender. Move them to the ice water with the eggs for 1 minute, then drain and pat dry. At the same time, set a 12-inch cast-iron or heavy stainless skillet over high heat with the 1 tbsp neutral oil so it is shimmering hot by the time the beans are out. About 3 minutes.', '["green-beans","neutral-oil"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_salade-nicoise-seared-tuna_v2', 5, 'Sear the tuna', 'Season the tuna on all sides with 3/4 tsp kosher salt and 1/2 tsp cracked pepper, pressing the pepper in. Lay the steaks in the shimmering skillet and do not move them: 3 minutes per side until the center reaches 145 F. Briefly sear the edges with tongs. Move to a cutting board. About 7 minutes. Optional traditional preparation: a rare, deep-red center, about 115 F, for 1 1/2 to 2 minutes per side. That lower temperature does not meet the USDA/FDA recommendation and carries higher risk, especially for young children, pregnant people, older adults, and anyone immunocompromised.', '["ahi-tuna-steaks","kosher-salt","black-pepper"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_salade-nicoise-seared-tuna_v2', 6, 'Rest the tuna; peel the eggs', 'Let the tuna rest 3 to 4 minutes. Meanwhile peel the eggs under a trickle of water and halve them lengthwise; the yolks should be jammy and just set at the edges. About 4 minutes.', '["ahi-tuna-steaks","eggs"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_salade-nicoise-seared-tuna_v2', 7, 'Slice and compose', 'Slice the tuna across the grain into 1/2-inch slices. Line a large platter or 4 shallow plates with lettuce leaves. Arrange the dressed potatoes, green beans, cherry tomatoes, egg halves, and olives in separate groups, and fan the tuna slices in the center. Scatter the capers and parsley; drape the anchovy fillets over the eggs if using. Spoon the remaining vinaigrette over everything and finish with the last 1/4 tsp cracked pepper. Serve right away while the potatoes are warm. About 5 minutes. kitchen_tested is false.', '["ahi-tuna-steaks","butter-lettuce","baby-potatoes","green-beans","cherry-tomatoes","eggs","olives","capers","flat-leaf-parsley","anchovy-fillets","extra-virgin-olive-oil","black-pepper"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_seared-duck-breast-cherry_v2', 1, 'Score and season', 'Score the duck skin. Salt the duck with 1 1/4 tsp salt and the pepper. Halve the cherries if they are large, and mince the shallot. Save the last 1/4 tsp salt for the arugula. About 10 minutes.', '["duck-breasts","kosher-salt","black-pepper","cherries","shallot"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_seared-duck-breast-cherry_v2', 2, 'Sear the skin', 'Put the breasts skin-side down in a cold skillet. Set the heat to medium. Sear until the skin is crisp and golden and the fat has rendered, about 10 minutes, pouring off fat as it collects and saving 1 tbsp. Flip and sear the flesh side about 7 minutes, to 165 F. Rest the duck on a plate for 5 minutes. Optional traditional preparation: a rosy interior, about 135 F, after about 3 minutes on the flesh side. That lower temperature does not meet the USDA/FDA recommendation and carries higher risk, especially for young children, pregnant people, older adults, and anyone immunocompromised.', '["duck-breasts"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_seared-duck-breast-cherry_v2', 3, 'Cherry sauce and arugula', 'Pour off all but 1 tsp of fat. Cook the shallot 30 seconds. Add the cherries, vinegar, wine, honey, and thyme. Simmer until the sauce coats a spoon, about 6 minutes, while the duck rests. Slice the duck. Toss the arugula with the reserved 1 tbsp of rendered fat and the last 1/4 tsp salt. Cook is 26 minutes.', '["shallot","cherries","red-wine-vinegar","red-wine","honey","thyme","arugula","duck-breasts","kosher-salt"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_seared-scallops-parsnip-puree_v2', 1, 'Prep', 'Peel the parsnips and cut into 1-inch pieces. Pull the small side muscle off each scallop, then lay the scallops on a paper-towel-lined plate, pat the tops very dry, and refrigerate uncovered. Pick and dry the sage leaves. Halve the lemon.', '["parsnips","sea-scallops","fresh-sage","lemon"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_seared-scallops-parsnip-puree_v2', 2, 'Simmer the parsnips', 'Put the parsnips, milk, water, and 1 tsp salt in a medium saucepan. Bring to a bare simmer over medium, about 5 minutes (watch that the milk does not boil over), then simmer gently until very tender, about 15 minutes.', '["parsnips","whole-milk","water","kosher-salt"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_seared-scallops-parsnip-puree_v2', 3, 'Fry the sage in brown butter', 'While the parsnips simmer, melt 4 tbsp butter in a small skillet over medium. Once it foams, add the sage leaves in a single layer and fry until crisp and the butter turns nutty brown, 2 to 3 minutes. Lift the leaves onto a paper towel and sprinkle lightly with salt; pour the brown butter into a small bowl. Takes 4 to 5 minutes, inside the parsnip simmer.', '["unsalted-butter","fresh-sage","kosher-salt"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_seared-scallops-parsnip-puree_v2', 4, 'Blend the purée', 'With a slotted spoon, move the parsnips to a blender. Add 2 tbsp butter and about 1/2 cup of the cooking liquid and blend until completely silky, 2 to 3 minutes, adding more liquid a splash at a time until it is soft and spoonable. Taste for salt. Return to the saucepan, cover, and keep warm on the lowest heat.', '["parsnips","unsalted-butter","whole-milk","kosher-salt"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_seared-scallops-parsnip-puree_v2', 5, 'Sear the scallops', 'Heat a 12-inch heavy skillet (cast iron or stainless) over high until very hot, about 2 minutes. Season the scallops with 1/2 tsp salt and the pepper. Add 1 tbsp oil and half the scallops, flat side down, spaced apart. Sear without moving until a deep golden-brown crust forms, about 2 minutes, then flip and cook 2 to 3 minutes more, until opaque and firm throughout. Optional traditional preparation: scallops that are still translucent in the center, about 120 F to 125 F. That lower temperature does not meet the USDA/FDA recommendation and carries higher risk, especially for young children, pregnant people, older adults, and anyone immunocompromised. Move to a plate and repeat with the remaining oil and scallops.', '["neutral-oil","sea-scallops","kosher-salt","black-pepper"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_seared-scallops-parsnip-puree_v2', 6, 'Dress the salad and plate', 'Toss the arugula with the olive oil, a squeeze from half the lemon, and a pinch of salt. Swoosh a generous spoonful of purée on each plate, set 4 scallops crust side up on it, spoon over the sage brown butter, and top with the crispy sage. Add a small mound of arugula and a lemon wedge cut from the remaining half. Serve right away. kitchen_tested is false.', '["baby-arugula","extra-virgin-olive-oil","lemon","kosher-salt","parsnips","sea-scallops","unsalted-butter","fresh-sage"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_sesame-soba-noodle-bowl_v3', 1, 'Cook the noodles', 'Boil the soba noodles in the unsalted water for 4 to 5 minutes, until tender. The water is unsalted because the soy dressing seasons the noodles, which is how this cold bowl is built, not a 1% pasta pot. Drain and rinse under cold water.', '["soba noodles","water"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_sesame-soba-noodle-bowl_v3', 2, 'Dress', 'Toss the cooled noodles with the sesame oil, rice vinegar, soy sauce, Diamond Crystal kosher salt, and the carrot. Taste a noodle and add a pinch more salt only if the soy still tastes thin.', '["sesame oil","rice vinegar","soy sauce","Diamond Crystal kosher salt","carrot","soba noodles"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_sesame-soba-noodle-bowl_v3', 3, 'Top', 'Top with the edamame and the sesame seeds.', '["edamame","sesame seeds"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_sheet-pan-lemon-herb-chicken_v3', 1, 'Season and arrange', 'Heat the oven to 425 F. Toss the chicken thighs and potatoes with the neutral oil, half the lemon, the dried oregano, dried thyme, garlic, 8 g of the Diamond Crystal kosher salt, and the black pepper.', '["chicken thighs","potatoes","neutral oil","lemon","dried oregano","dried thyme","garlic","Diamond Crystal kosher salt","black pepper"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_sheet-pan-lemon-herb-chicken_v3', 2, 'Roast', 'Roast at 425 F until the chicken reaches 165 F, 35 to 40 minutes. Add the green beans tossed with the remaining 2 g Diamond Crystal kosher salt for about the last 12 minutes.', '["chicken thighs","green beans","Diamond Crystal kosher salt"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_sheet-pan-lemon-herb-chicken_v3', 3, 'Rest', 'Rest 5 minutes, then squeeze the remaining lemon over the top.', '["lemon","chicken thighs"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_smoky-lentil-sweet-potato-stew_v3', 1, 'Sweat and bloom', 'Cook the yellow onion in the olive oil with the Diamond Crystal kosher salt over medium heat until soft, about 6 minutes. Add the garlic and smoked paprika and cook 1 minute.', '["yellow onion","olive oil","Diamond Crystal kosher salt","garlic","smoked paprika"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_smoky-lentil-sweet-potato-stew_v3', 2, 'Simmer', 'Add the red lentils, sweet potato, diced tomatoes, vegetable broth, and black pepper. Simmer 25 minutes, until the sweet potato is tender and the lentils have broken down. Taste the stew and add salt only if the broth did not already season it.', '["red lentils","sweet potato","diced tomatoes","vegetable broth","black pepper"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_smoky-lentil-sweet-potato-stew_v3', 3, 'Thicken and serve', 'Mash a portion of the stew against the side of the pot until it thickens. Leave some sweet potato cubes visible.', '["sweet potato","red lentils"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_spanish-potato-tortilla_v2', 1, 'Slice', 'Slice the potatoes into thin rounds and the onion thin. About 15 minutes.', '["yukon-gold-potatoes","yellow-onion"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_spanish-potato-tortilla_v2', 2, 'Shallow-fry the potatoes', 'Heat the olive oil in a 10-inch skillet over medium. Add the potatoes and onion, keep them in a shallow layer of oil, and cook, turning gently, until the potatoes are tender but not browned hard, about 18 minutes. Salt them with 8 g of the Diamond Crystal kosher salt as they cook. Taste one potato, which is cooked, before it goes into the eggs, and add a pinch more salt only if it tastes flat. Drain, and reserve the oil.', '["olive-oil","yukon-gold-potatoes","yellow-onion","kosher-salt"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_spanish-potato-tortilla_v2', 3, 'Set and flip', 'Beat the eggs with the remaining 3 g Diamond Crystal kosher salt and the pepper. Fold in the potatoes and onion. Return 2 tbsp of the oil to the skillet over medium-low. Pour in the eggs and cook until the edge is set and the top is still moist, about 8 minutes. Invert onto a plate, slide it back, and cook about 4 minutes more, until the center is just firm. Scatter the parsley and cut into wedges.', '["eggs","kosher-salt","black-pepper","yukon-gold-potatoes","yellow-onion","olive-oil","parsley"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_steak-au-poivre-smashed-potatoes_v2', 1, 'Preheat and prep', 'Turn the oven on to 450 F to preheat. Put the potatoes in a 4-quart pot with 10 cups cold water and 24 g of the Diamond Crystal kosher salt (about 1% by weight) over high heat. Crack the peppercorns coarsely. Season the steaks with 11 g of the Diamond Crystal kosher salt and press the cracked pepper into both sides. Mince the shallot and snip the chives.', '["potato-water","baby-potatoes","kosher-salt","black-peppercorns","strip-steaks","shallot","chives"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_steak-au-poivre-smashed-potatoes_v2', 2, 'Boil the potatoes', 'Bring the 10 cups of salted water to a boil and cook the potatoes until a knife slides in, about 18 minutes. Drain and let them steam dry 2 minutes.', '["potato-water","baby-potatoes"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_steak-au-poivre-smashed-potatoes_v2', 3, 'Smash', 'Spread the potatoes on the sheet pan, press each one flat to about 1/2 inch, drizzle with the olive oil, and sprinkle with 2 g of the Diamond Crystal kosher salt.', '["baby-potatoes","olive-oil","kosher-salt"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_steak-au-poivre-smashed-potatoes_v2', 4, 'Roast the potatoes', 'Roast in the preheated 450 F oven until deep golden and crispy at the edges, 22 minutes.', '["baby-potatoes"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_steak-au-poivre-smashed-potatoes_v2', 5, 'Sear the steaks', 'With 12 minutes left on the potatoes, heat the oil in the cast-iron skillet over high until smoking. Sear the steaks, turning as needed, until the center of each steak is 145 F. Move them to a plate and rest 3 minutes. A pinker center is a personal texture preference and is not the instruction in this recipe. Runs inside the potato roast (overlap stated).', '["neutral-oil","strip-steaks"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_steak-au-poivre-smashed-potatoes_v2', 6, 'Make the sauce', 'Pour off all but a thin film of fat and lower the heat to medium. Add the butter and shallot and cook 1 minute. Take the pan off the heat, add the brandy, return it to the heat, and simmer until almost gone, about 1 minute. Whisk in the cream, the Dijon, and the remaining 1 g Diamond Crystal kosher salt. Simmer until the sauce coats a spoon, 2 to 3 minutes, adding the steak juices. Taste the sauce and add salt only if it still tastes flat. Spoon it over the steaks and serve with the potatoes and chives.', '["butter","shallot","brandy","heavy-cream","dijon-mustard","strip-steaks","baby-potatoes","chives"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_tex-mex-steak-fajitas_v2', 1, 'Prep and marinate', 'Toss the steak in the medium bowl with 1/4 cup lime juice, the garlic, cumin, chili powder, 1 tbsp oil, and 1 1/4 tsp salt, and let it sit 15 minutes while you work. Slice the peppers and 1 onion. Dice the tomatoes and 1/4 onion, mince the jalapeno, and chop the cilantro; stir them in the small bowl with the remaining lime juice and 1/4 tsp salt for pico. Slice the avocado.', '["steak","lime-juice","garlic","cumin","chili-powder","oil","salt","bell-peppers","onion","tomatoes","jalapeno","cilantro","avocado"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_tex-mex-steak-fajitas_v2', 2, 'Sear the steak', 'Heat the cast-iron skillet over high until smoking, about 4 minutes. Add 1 tbsp oil and sear 2 pieces of steak (pat off excess marinade) until deeply browned and 145 F, about 4 minutes per side. Repeat (2 batches). Rest on the cutting board 5 minutes. Optional traditional preparation: medium-rare, about 130 F. That lower temperature does not meet the USDA/FDA recommendation and carries higher risk, especially for young children, pregnant people, older adults, and anyone immunocompromised.', '["oil","steak"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_tex-mex-steak-fajitas_v2', 3, 'Char the peppers', 'While the steak rests (overlap stated): add 1 tbsp oil, the peppers, sliced onion, and 1/2 tsp salt to the skillet and cook, tossing, until charred at the edges and crisp-tender, about 6 minutes.', '["oil","bell-peppers","onion","salt"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_tex-mex-steak-fajitas_v2', 4, 'Warm the tortillas', 'Warm each tortilla in the skillet over medium, about 20 seconds per side, and wrap in the kitchen towel.', '["tortillas"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_tex-mex-steak-fajitas_v2', 5, 'Slice and serve', 'Slice the steak thinly across the grain and pile it with the peppers and onions. Serve with tortillas, pico, avocado, and sour cream.', '["steak","bell-peppers","onion","tortillas","avocado","sour-cream"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_thai-basil-eggplant-stir-fry_v3', 1, 'Cook the rice', 'Rinse the jasmine rice. Bring it to a boil with the water and the Diamond Crystal kosher salt. Cover and simmer 15 minutes. Rest covered 5 minutes, then fluff. The 4 g in 2.25 cups is about 0.7% and the water is absorbed.', '["jasmine rice","water","Diamond Crystal kosher salt"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_thai-basil-eggplant-stir-fry_v3', 2, 'Brown the eggplant', 'While the rice cooks, heat 2 tbsp of the neutral oil in a wide skillet over high heat. Stir-fry the Japanese eggplant in a single layer, in two batches if needed, until browned and creamy in the center, 6 to 8 minutes per batch.', '["neutral oil","Japanese eggplant"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_thai-basil-eggplant-stir-fry_v3', 3, 'Season', 'Add the remaining 1 tbsp neutral oil, the garlic, and the red pepper flakes. Cook 30 seconds. Add the soy sauce and the granulated sugar and toss to coat. Take the pan off the heat and stir in the Thai basil until just wilted. Taste a piece of eggplant and add a splash more soy only if it tastes flat. Fish sauce is not in this version because it would add a finfish allergen and drop the plant-based claim.', '["neutral oil","garlic","red pepper flakes","soy sauce","granulated sugar","Thai basil","Japanese eggplant"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_thai-basil-eggplant-stir-fry_v3', 4, 'Serve', 'Serve the eggplant and basil over the rice.', '["Japanese eggplant","Thai basil","jasmine rice"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_thai-yum-nua-beef-salad_v2', 1, 'Prep', 'Rinse the rice. Cut the steak in half crosswise so it fits the skillet, pat it dry, and season with 1 tsp salt and the pepper. Whisk the lime juice, fish sauce, brown sugar, chiles, and garlic in the large bowl until the sugar dissolves. Slice the cucumber, halve the tomatoes, slice the shallots, cut the scallions, pick the mint and cilantro, and separate the romaine leaves.', '["jasmine-rice","flank-steak","kosher-salt","black-pepper","lime","fish-sauce","brown-sugar","bird-chiles","garlic","cucumber","tomatoes","shallots","scallions","mint","cilantro","romaine"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_thai-yum-nua-beef-salad_v2', 2, 'Start the rice', 'Combine the rice, 2 1/4 cups water, and 1/2 tsp salt in a 2-quart saucepan. Bring to a boil over high, about 4 minutes, then cover, turn to low, and cook 15 minutes; leave it covered off the heat to rest 10 minutes. The covered cooking and rest run inside steps 3 to 6 (overlap stated).', '["jasmine-rice","rice-water","kosher-salt"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_thai-yum-nua-beef-salad_v2', 3, 'Sear the steak', 'Heat a 12-inch cast-iron skillet over high until it just smokes, about 4 minutes. Add the oil and the steak and sear without moving it until deeply browned, about 6 minutes per side, until 145 F at the thickest point. Optional traditional preparation: medium-rare, about 130 F. That lower temperature does not meet the USDA/FDA recommendation and carries higher risk, especially for young children, pregnant people, older adults, and anyone immunocompromised.', '["neutral-oil","flank-steak"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_thai-yum-nua-beef-salad_v2', 4, 'Rest', 'Move the steak to the cutting board and rest 5 minutes.', '["flank-steak"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_thai-yum-nua-beef-salad_v2', 5, 'Slice and toss', 'Slice the steak thinly against the grain. Add the slices and their juices to the dressing with the cucumber, tomatoes, shallots, and scallions and toss, then fold in the mint and cilantro.', '["flank-steak","cucumber","tomatoes","shallots","scallions","mint","cilantro"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_thai-yum-nua-beef-salad_v2', 6, 'Serve', 'Line a platter with the romaine, pile the salad on top with its dressing, and serve the rice alongside.', '["romaine","flank-steak","jasmine-rice"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_white-bean-kale-soup_v3', 1, 'Saute the fennel', 'Cook the fennel in the neutral oil over medium heat for 5 minutes. Add the garlic and cook 1 minute.', '["fennel","neutral oil","garlic"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_white-bean-kale-soup_v3', 2, 'Simmer', 'Add the cannellini beans, vegetable broth, and diced tomatoes. Simmer 20 minutes.', '["cannellini beans","vegetable broth","diced tomatoes"]');
INSERT INTO catalog_step (recipe_version_id, step_number, title, body, ingredient_refs_json) VALUES ('rv_white-bean-kale-soup_v3', 3, 'Wilt the kale and season', 'Stir in the kale and cook about 5 minutes, until tender. Stir in the Diamond Crystal kosher salt and the black pepper. Taste a spoonful and stop if the broth was already salty enough. Cheese, sausage, and cream are not in this soup because the package is dairy-free and plant-based, and those foods would add allergens it does not claim.', '["kale","Diamond Crystal kosher salt","black pepper"]');
