INSERT OR IGNORE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at, effort_level, ingredient_complexity, classification_hash) VALUES ('rv_ethiopian-beef-tibs_v2', 'rcp_ethiopian-beef-tibs', 'ethiopian-beef-tibs', 2, 'Ethiopian Berbere Beef Tibs', 'Cubed beef quickly sautéed with onion, garlic, ginger, and berbere until deeply spiced and browned, finished with tomato and herbs. Served with rice or greens (injera optional if available).', 4, 15, 29, 44, 'Medium-high to sear beef; medium for onion base; medium-high to finish. No oven. No grill required.', 'Beef cubes browned outside and cooked to 145 F in the center, then a 3-minute rest (USDA whole-muscle beef). Onions soft and brick-red with berbere. Tomato melted into the base. Not a long braise. Optional traditional preparation: medium cubes, about 135 F to 140 F. That lower temperature does not meet the USDA/FDA recommendation and carries higher risk, especially for young children, pregnant people, older adults, and anyone immunocompromised. kitchen_tested is false.', '[]', '[]', 'null', '[{"component_id":"berbere-beef","name":"berbere-seasoned beef cubes","made_in_recipe":true,"store_bought":false,"ingredients":["beef sirloin","berbere","kosher salt","black pepper"]},{"component_id":"onion-berbere-base","name":"onion berbere base","made_in_recipe":true,"store_bought":false,"ingredients":["yellow onion","garlic","fresh ginger","berbere","smoked paprika","tomato","neutral oil"]}]', 'published', 'draft', 'global', NULL, '4d23223812d2fe0b004cfee81dca613c83281d9a1241d5510f7e08035f114ed4', 'flavorweave-catalog-package', 'catalog/ethiopian-beef-tibs/v2.json', '2026-10-04T00:00:00.000Z', 'moderate', 'standard', '08ceede8e31d0536861737ed10ce02ecde3d242f006e7c41e7d6c307f16cc5ec');
INSERT OR IGNORE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at, effort_level, ingredient_complexity, classification_hash) VALUES ('rv_ginger-scallion-fish-packets_v3', 'rcp_ginger-scallion-fish-packets', 'ginger-scallion-fish-packets', 3, 'Ginger Scallion Fish Packets', 'White fish and bok choy steamed in foil with ginger, scallion, and soy, with rice salted in the pot, served with the packet juices.', 4, 15, 20, 35, 'Oven 400 F, and a saucepan for the rice.', 'Fish flakes and is opaque in the center at 145 F. Bok choy is tender. FDA seafood temperature is 145 F.', '["oven","stovetop"]', '[]', 'null', '[]', 'published', 'draft', 'global', NULL, '8da863e8f3b68d9162dc9720b22777d591eaa375d42289121e18122a78fa78e5', 'flavorweave-legacy-audit-draft', 'catalog/ginger-scallion-fish-packets/v3.json', '2026-10-04T00:00:00.000Z', 'easy', 'simple', 'babd7dabd7743db6960cd85230f4a7cab0c70b57bc8930feeaf69b78e19cca59');
INSERT OR IGNORE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at, effort_level, ingredient_complexity, classification_hash) VALUES ('rv_gochujang-grilled-flank-steak_v2', 'rcp_gochujang-grilled-flank-steak', 'gochujang-grilled-flank-steak', 2, 'Gochujang Grilled Flank Steak', 'Thin-sliced grilled flank steak in a short gochujang marinade, with a sharp cucumber and scallion salad.', 4, 25, 27, 52, 'Direct grill heat, about 450–500°F.', '145 F in the center, then a 5-minute rest (USDA whole-muscle beef). Slice against the grain. Optional traditional preparation: medium-rare, 130 F to 135 F. That lower temperature does not meet the USDA/FDA recommendation and carries higher risk, especially for young children, pregnant people, older adults, and anyone immunocompromised.', '[]', '[]', 'null', '[{"component_id":"gochujang-marinade","name":"gochujang marinade","made_in_recipe":true,"store_bought":false,"ingredients":["gochujang","soy sauce","rice vinegar","toasted sesame oil","brown sugar","garlic","fresh ginger","black pepper","scallions"]},{"component_id":"scallion-cucumber-salad","name":"scallion cucumber salad","made_in_recipe":true,"store_bought":false,"ingredients":["cucumber","scallions","rice vinegar","toasted sesame oil","kosher salt","sesame seeds"]}]', 'published', 'draft', 'global', NULL, 'c792f5c5744540c669fb2414e56590cd19e2e26bc9110652437d121085c9b7ae', 'flavorweave-catalog-package', 'catalog/gochujang-grilled-flank-steak/v2.json', '2026-10-04T00:00:00.000Z', 'moderate', 'standard', '08ceede8e31d0536861737ed10ce02ecde3d242f006e7c41e7d6c307f16cc5ec');
INSERT OR IGNORE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at, effort_level, ingredient_complexity, classification_hash) VALUES ('rv_grilled-swordfish-olive-caper_v2', 'rcp_grilled-swordfish-olive-caper', 'grilled-swordfish-olive-caper', 2, 'Grilled Swordfish with Olive-Caper Relish', 'Thick grilled swordfish steaks and grilled fennel, with a chopped olive, caper, and anchovy relish.', 4, 18, 30, 48, 'Direct grill heat, about 450-500 F.', 'Pull swordfish at 145 F in the center, then rest 3 minutes (FDA finfish). The flesh should be opaque and flake under pressure, not chalky. Optional traditional preparation: a center just losing translucence, 130 F to 135 F. That lower temperature does not meet the USDA/FDA recommendation and carries higher risk, especially for young children, pregnant people, older adults, and anyone immunocompromised. kitchen_tested is false.', '[]', '[]', 'null', '[{"component_id":"olive-caper-relish","name":"olive-caper relish","made_in_recipe":true,"store_bought":false,"ingredients":["pitted green olives","capers","anchovy fillets","garlic","lemon","fresh parsley","olive oil","kosher salt","red pepper flakes"]}]', 'published', 'draft', 'global', NULL, '0fa42ef86d8e9c82e705dfe3d1347eb479986e9d46d18cbf05be14723e8e12fe', 'flavorweave-catalog-package', 'catalog/grilled-swordfish-olive-caper/v2.json', '2026-10-04T00:00:00.000Z', 'moderate', 'standard', '08ceede8e31d0536861737ed10ce02ecde3d242f006e7c41e7d6c307f16cc5ec');
INSERT OR IGNORE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at, effort_level, ingredient_complexity, classification_hash) VALUES ('rv_harissa-roasted-carrots-feta_v3', 'rcp_harissa-roasted-carrots-feta', 'harissa-roasted-carrots-feta', 3, 'Harissa Roasted Carrots with Feta', 'Harissa-roasted carrots with feta, mint, lemon, and couscous cooked in salted water.', 4, 15, 30, 45, 'Oven 425 F.', 'Carrots tender and browned at the edges. Couscous fluffy.', '["oven","roast"]', '["dairy"]', 'null', '[]', 'published', 'draft', 'global', NULL, '079e37400b938b707199340991d3dad0b3bdf62cf42a4abb6738839e31be7641', 'flavorweave-legacy-catalog-package', 'catalog/harissa-roasted-carrots-feta/v3.json', '2026-10-04T00:00:00.000Z', 'easy', 'simple', 'babd7dabd7743db6960cd85230f4a7cab0c70b57bc8930feeaf69b78e19cca59');
INSERT OR IGNORE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at, effort_level, ingredient_complexity, classification_hash) VALUES ('rv_lemon-garlic-shrimp-pasta_v3', 'rcp_lemon-garlic-shrimp-pasta', 'lemon-garlic-shrimp-pasta', 3, 'Lemon Garlic Shrimp Pasta', 'Shrimp seared with garlic in olive oil and tossed with lemon, parsley, and pasta from a salted pot.', 4, 15, 15, 30, 'Stovetop.', 'Shrimp are pink and opaque and the thickest piece is 145 F. Pasta is al dente.', '["stovetop"]', '[]', 'null', '[]', 'published', 'published', 'global', NULL, '1dc8ddaf4bb180777c080472100fb11c36455fae219c4d65d5315cc9f2b808f7', 'flavorweave-legacy-catalog-package', 'catalog/lemon-garlic-shrimp-pasta/v3.json', '2026-10-04T00:00:00.000Z', 'moderate', 'simple', 'fff648ac7b6240cd1d7f5fe3af9d8fd777f0aa0b0a9735e530ee04a1e367da2d');
INSERT OR IGNORE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at, effort_level, ingredient_complexity, classification_hash) VALUES ('rv_linguine-with-clams_v2', 'rcp_linguine-with-clams', 'linguine-with-clams', 2, 'Linguine with Clams', 'Littleneck clams steamed open in garlic and white wine, tossed with linguine, parsley, and lemon. No cheese and no butter.', 4, 15, 18, 33, 'A large pot of boiling water for the pasta. A 12-inch skillet or wide pot over medium for the clams.', 'Pasta tender with a slight bite. Clams open. Any clam that stays shut is discarded. Sauce glossy from the clam liquor and olive oil, not creamy.', '["stovetop"]', '[]', 'null', '[]', 'published', 'draft', 'global', NULL, '8f5e194a67e4e20ffcf71b4a324af2b7a0e3c6065ad4dbf5a3a8ed066725194e', 'flavorweave-catalog-package', 'catalog/linguine-with-clams/v2.json', '2026-10-04T00:00:00.000Z', 'moderate', 'standard', '08ceede8e31d0536861737ed10ce02ecde3d242f006e7c41e7d6c307f16cc5ec');
INSERT OR IGNORE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at, effort_level, ingredient_complexity, classification_hash) VALUES ('rv_malaysian-curry-laksa_v2', 'rcp_malaysian-curry-laksa', 'malaysian-curry-laksa', 2, 'Malaysian Curry Laksa with Shrimp', 'A rich, spicy coconut noodle soup: a homemade paste of shallots, lemongrass, ginger, garlic, dried chiles, turmeric, and shrimp paste, sizzled in oil and simmered with coconut milk and stock, then poured over rice vermicelli and shrimp and piled with bean sprouts, cucumber, mint, and lime.', 4, 25, 29, 54, 'Medium to cook the paste until the oil separates; medium-low simmer; gentle simmer to poach the shrimp; boil for the noodles.', 'Paste dark and fragrant with oil separating; broth creamy and orange-red; shrimp pink, opaque, and firm (FDA shellfish: cook until the flesh is opaque and firm). Optional traditional preparation: shrimp that are pink and still translucent in the center, about 120 F to 125 F. That lower temperature does not meet the USDA/FDA recommendation and carries higher risk, especially for young children, pregnant people, older adults, and anyone immunocompromised.', '["saute","simmer","boil"]', '[]', 'null', '[{"component_id":"paste","name":"laksa paste","made_in_recipe":true,"store_bought":false,"ingredients":["shallots","garlic","ginger","lemongrass","dried chiles","turmeric","coriander","shrimp paste","oil"]},{"component_id":"broth","name":"coconut laksa broth with shrimp","made_in_recipe":true,"store_bought":false,"ingredients":["coconut milk","chicken stock","fish sauce","brown sugar","shrimp"]},{"component_id":"noodles","name":"rice vermicelli","made_in_recipe":true,"store_bought":false,"ingredients":["rice vermicelli","water"]},{"component_id":"garnish","name":"fresh garnishes","made_in_recipe":true,"store_bought":false,"ingredients":["bean sprouts","cucumber","mint","limes"]}]', 'published', 'draft', 'global', NULL, '32763c3c7d32903558605d50e95f8a9d402f420e16aec63e4c8c72bae8b64781', 'flavorweave-catalog-package', 'catalog/malaysian-curry-laksa/v2.json', '2026-10-04T00:00:00.000Z', 'involved', 'adventurous', '6ee7bb37273cbc12eff6d5be73cdb6c79a88a65cdfe5ea686de96c0b7a43a78d');
INSERT OR IGNORE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at, effort_level, ingredient_complexity, classification_hash) VALUES ('rv_maple-mustard-glazed-salmon_v3', 'rcp_maple-mustard-glazed-salmon', 'maple-mustard-glazed-salmon', 3, 'Maple Mustard Glazed Salmon', 'Salmon fillets roasted with a maple-Dijon glaze until the center reaches 145 F, with asparagus roasted beside them and a lemon-dill finish.', 4, 15, 15, 30, 'Oven 425 F, then a short broil.', 'Cook the salmon to 145 F in the thickest part (FDA seafood guidance: https://www.fda.gov/food/buy-store-serve-safe-food/selecting-and-serving-fresh-and-frozen-seafood-safely). The center is opaque and the fish flakes. Rest 3 minutes. A thin fillet does not need to be pulled early for carryover.', '["oven"]', '[]', 'null', '[]', 'published', 'draft', 'global', NULL, 'b069e14b0533b8d6665037ac8a30c6816463391740245eaea89e96bff036d251', 'flavorweave-legacy-audit-draft', 'catalog/maple-mustard-glazed-salmon/v3.json', '2026-10-04T00:00:00.000Z', 'easy', 'simple', 'babd7dabd7743db6960cd85230f4a7cab0c70b57bc8930feeaf69b78e19cca59');
INSERT OR IGNORE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at, effort_level, ingredient_complexity, classification_hash) VALUES ('rv_moroccan-chickpea-skillet_v3', 'rcp_moroccan-chickpea-skillet', 'moroccan-chickpea-skillet', 3, 'Moroccan Chickpea Skillet', 'Chickpeas with ras el hanout, garlic, preserved lemon, and spinach over couscous, salted with the lemon and checked before serving.', 4, 10, 15, 25, 'Stovetop.', 'Chickpeas glossy, spinach just wilted, couscous fluffy.', '["stovetop"]', '["plant","dairy-free"]', '{"couscous":"This version uses wheat couscous. A gluten-free stand-in would change the allergen list and is not this version.","preserved lemon":"Rind only. Do not chop in the salty pulp, and do not swap in fresh lemon wedges."}', '[]', 'published', 'unpublished_curator_draft', 'global', NULL, '55980a495f47c045f3acb0fd5164bbc6e03b9b3e9ba6e86029e2ad37c6ee60a8', 'flavorweave-legacy-catalog-package', 'catalog/moroccan-chickpea-skillet/v3.json', '2026-10-04T00:00:00.000Z', 'easy', 'standard', '699d309589d22307c254526b29a51d18b9e88d2063d14aeade9921f0eab2c506');
INSERT OR IGNORE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at, effort_level, ingredient_complexity, classification_hash) VALUES ('rv_mushroom-walnut-bolognese_v3', 'rcp_mushroom-walnut-bolognese', 'mushroom-walnut-bolognese', 3, 'Mushroom Walnut Bolognese', 'Mushroom and walnut sauce over spaghetti, salted as the mushrooms brown and in the pasta water.', 4, 15, 30, 45, 'Stovetop.', 'Mushrooms deeply browned. Sauce thick. Pasta al dente.', '["skillet"]', '["plant","dairy-free"]', 'null', '[]', 'published', 'draft', 'global', NULL, '2195c9490c837fb080ac20255345a622ffb3a81e1b0ffd78710f4776fe40c145', 'flavorweave-legacy-catalog-package', 'catalog/mushroom-walnut-bolognese/v3.json', '2026-10-04T00:00:00.000Z', 'moderate', 'simple', 'fff648ac7b6240cd1d7f5fe3af9d8fd777f0aa0b0a9735e530ee04a1e367da2d');
INSERT OR IGNORE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at, effort_level, ingredient_complexity, classification_hash) VALUES ('rv_nigerian-beef-suya-skewers_v2', 'rcp_nigerian-beef-suya-skewers', 'nigerian-beef-suya-skewers', 2, 'Nigerian Beef Suya Skewers with Tomato-Onion Salad and Rice', 'Thin strips of beef coated in yaji, a smoky, spicy ground-peanut spice blend with ginger, garlic, paprika, and cayenne, grilled hot on skewers and served with sliced tomato, red onion, cabbage, lime, and steamed jasmine rice.', 4, 20, 41, 61, 'High direct grill heat (or a grill pan on high); low simmer for the rice.', 'Beef charred at the edges and cooked to 145 F in thicker pieces, then a 3-minute rest (USDA whole-muscle beef). Rice tender with no liquid left. Optional traditional preparation: at least medium, about 140 F. That lower temperature does not meet the USDA/FDA recommendation and carries higher risk, especially for young children, pregnant people, older adults, and anyone immunocompromised.', '["grill","simmer"]', '[]', 'null', '[{"component_id":"yaji","name":"yaji suya spice","made_in_recipe":true,"store_bought":false,"ingredients":["roasted peanuts","ground ginger","garlic powder","onion powder","smoked paprika","cayenne","salt"]},{"component_id":"suya","name":"grilled beef suya","made_in_recipe":true,"store_bought":false,"ingredients":["beef sirloin","oil","yaji"]},{"component_id":"salad","name":"tomato, onion, and cabbage","made_in_recipe":true,"store_bought":false,"ingredients":["tomatoes","red onion","cabbage","lime"]},{"component_id":"rice","name":"jasmine rice","made_in_recipe":true,"store_bought":false,"ingredients":["jasmine rice","water","salt"]}]', 'published', 'draft', 'global', NULL, '091bc1d90966df13cbfe3cf658957eb6b80b299f4a73e55c9bec8f74b5c71798', 'flavorweave-catalog-package', 'catalog/nigerian-beef-suya-skewers/v2.json', '2026-10-04T00:00:00.000Z', 'moderate', 'simple', 'fff648ac7b6240cd1d7f5fe3af9d8fd777f0aa0b0a9735e530ee04a1e367da2d');
INSERT OR IGNORE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at, effort_level, ingredient_complexity, classification_hash) VALUES ('rv_pan-seared-halibut-lemon-butter-corn_v2', 'rcp_pan-seared-halibut-lemon-butter-corn', 'pan-seared-halibut-lemon-butter-corn', 2, 'Pan-Seared Halibut with Lemon Butter and Sweet Corn Saute', 'A 25-minute summer plate: thick halibut fillets seared golden and basted in garlicky lemon butter, served over a quick saute of sweet corn, cherry tomatoes, and scallions with torn basil.', 4, 8, 18, 26, 'Medium-high for the corn; medium-high to sear the fish, then medium to baste.', 'Halibut golden on one side, opaque, and 145 F in the center (FDA finfish). Corn bright and lightly browned. Optional traditional preparation: just opaque at 130 F to 135 F. That lower temperature does not meet the USDA/FDA recommendation and carries higher risk, especially for young children, pregnant people, older adults, and anyone immunocompromised.', '["sear","saute"]', '[]', 'null', '[{"component_id":"fish","name":"halibut with lemon butter","made_in_recipe":true,"store_bought":false,"ingredients":["halibut","oil","butter","garlic","lemon","salt","pepper"]},{"component_id":"corn","name":"corn saute","made_in_recipe":true,"store_bought":false,"ingredients":["corn","cherry tomatoes","scallions","basil","olive oil","salt"]}]', 'published', 'draft', 'global', NULL, '4378909c8189e0fe3df24a6207a9401888b96c0c3f88d123ed4d89fe45a93f4d', 'flavorweave-catalog-package', 'catalog/pan-seared-halibut-lemon-butter-corn/v2.json', '2026-10-04T00:00:00.000Z', 'easy', 'simple', 'babd7dabd7743db6960cd85230f4a7cab0c70b57bc8930feeaf69b78e19cca59');
INSERT OR IGNORE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at, effort_level, ingredient_complexity, classification_hash) VALUES ('rv_roasted-cauliflower-shawarma-plate_v3', 'rcp_roasted-cauliflower-shawarma-plate', 'roasted-cauliflower-shawarma-plate', 3, 'Roasted Cauliflower Shawarma Plate', 'Roasted shawarma-spiced cauliflower with a salted tahini-garlic sauce, cucumber, and warm pita.', 4, 15, 25, 40, 'Oven 425 F.', 'Cauliflower charred at the edges and tender at the stem. Sauce drizzle-thin.', '["oven"]', '[]', 'null', '[]', 'published', 'draft', 'global', NULL, '93790c0f7d8cbac90eae6569fae3ebef488ff0c3dc0650d4bd1bc5a16dc366e6', 'flavorweave-legacy-audit-draft', 'catalog/roasted-cauliflower-shawarma-plate/v3.json', '2026-10-04T00:00:00.000Z', 'easy', 'standard', '699d309589d22307c254526b29a51d18b9e88d2063d14aeade9921f0eab2c506');
INSERT OR IGNORE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at, effort_level, ingredient_complexity, classification_hash) VALUES ('rv_roasted-whole-branzino-salmoriglio_v2', 'rcp_roasted-whole-branzino-salmoriglio', 'roasted-whole-branzino-salmoriglio', 2, 'Roasted Whole Branzino with Salmoriglio and Lemon Potatoes', 'Two whole branzino stuffed with lemon, garlic, and oregano and roasted on a bed of crisp-edged sliced potatoes and red onion, then spooned with salmoriglio, the Sicilian lemon, oregano, garlic, and olive oil sauce.', 4, 15, 49, 64, 'Oven preheated to 450 F, rack in the middle.', 'Fish flesh opaque and lifting easily from the backbone, 145 F at the thickest point (FDA finfish); skin crisp at the edges. Potatoes golden and tender. Optional traditional preparation: 135 F to 140 F at the thickest point. That lower temperature does not meet the USDA/FDA recommendation and carries higher risk, especially for young children, pregnant people, older adults, and anyone immunocompromised.', '["roast"]', '[]', 'null', '[{"component_id":"fish","name":"roasted whole branzino","made_in_recipe":true,"store_bought":false,"ingredients":["branzino","lemon","garlic","oregano","olive oil","salt"]},{"component_id":"potatoes","name":"lemon potatoes and onion","made_in_recipe":true,"store_bought":false,"ingredients":["Yukon Gold potatoes","red onion","olive oil","salt"]},{"component_id":"salmoriglio","name":"salmoriglio","made_in_recipe":true,"store_bought":false,"ingredients":["lemon","oregano","garlic","parsley","chile flakes","olive oil","salt"]}]', 'published', 'draft', 'global', NULL, 'd7881a23ea23c08b4f54eb2e9167191a3089d5111eb79029798e971a63c33e98', 'flavorweave-catalog-package', 'catalog/roasted-whole-branzino-salmoriglio/v2.json', '2026-10-04T00:00:00.000Z', 'moderate', 'simple', 'fff648ac7b6240cd1d7f5fe3af9d8fd777f0aa0b0a9735e530ee04a1e367da2d');
INSERT OR IGNORE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at, effort_level, ingredient_complexity, classification_hash) VALUES ('rv_salade-nicoise-seared-tuna_v2', 'rcp_salade-nicoise-seared-tuna', 'salade-nicoise-seared-tuna', 2, 'Salade Niçoise with Seared Tuna', 'A dinner-sized composed salad: pepper-crusted seared ahi tuna sliced rare, warm baby potatoes tossed in Dijon-shallot vinaigrette, jammy 7-minute eggs, crisp green beans, cherry tomatoes, olives, and capers on butter lettuce. Dairy-free vinaigrette; no butter anywhere.', 4, 15, 32, 47, 'Stovetop only. High heat for the boiling water and a steady boil for potatoes/eggs/beans; high heat, shimmering oil for the tuna sear. No oven.', 'Potatoes knife-tender; eggs jammy (7 minutes from cold); beans bright green and crisp-tender; tuna seared on the outside and cooked to 145 F in the center (FDA finfish). Optional traditional preparation: a deep-red rare center, about 115 F. That lower temperature does not meet the USDA/FDA recommendation and carries higher risk, especially for young children, pregnant people, older adults, and anyone immunocompromised. kitchen_tested is false.', '[]', '[]', 'null', '[{"component_id":"dijon-shallot-vinaigrette","name":"Dijon-shallot vinaigrette (dairy-free)","made_in_recipe":true,"store_bought":false,"ingredients":["extra-virgin olive oil","red wine vinegar","Dijon mustard","shallot","garlic","kosher salt","black pepper"]},{"component_id":"one-pot-potatoes-eggs-beans","name":"warm vinaigrette potatoes, jammy eggs, and blanched green beans (one pot)","made_in_recipe":true,"store_bought":false,"ingredients":["baby potatoes","eggs","green beans","kosher salt","vinaigrette"]},{"component_id":"pepper-seared-tuna","name":"pepper-seared ahi tuna","made_in_recipe":true,"store_bought":false,"ingredients":["yellowfin tuna","neutral oil","kosher salt","black pepper"]},{"component_id":"composed-salad","name":"composed niçoise salad","made_in_recipe":true,"store_bought":false,"ingredients":["butter lettuce","cherry tomatoes","olives","capers","parsley","optional anchovies"]}]', 'published', 'draft', 'global', NULL, 'ba87cdf3d529123a00c7447f32edeb77e7bfc906390e57889a53e1c0c87d34b7', 'flavorweave-catalog-package', 'catalog/salade-nicoise-seared-tuna/v2.json', '2026-10-04T00:00:00.000Z', 'involved', 'simple', '5c96a847dece17be968649c3c11b24bd711058ea1c1d8e24db468d59544c5b1f');
INSERT OR IGNORE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at, effort_level, ingredient_complexity, classification_hash) VALUES ('rv_seared-duck-breast-cherry_v2', 'rcp_seared-duck-breast-cherry', 'seared-duck-breast-cherry', 2, 'Seared Duck Breast with Cherry Pan Sauce', 'Duck breasts with the skin seared until crisp, a cherry pan sauce, and arugula. No butter.', 4, 10, 26, 36, 'Medium skillet, starting with a cold pan so the skin renders. Medium for the sauce.', 'Skin crisp and golden, interior 165 F (USDA poultry), then a 5-minute rest. Sauce syrupy enough to coat a spoon. Optional traditional preparation: a rosy interior, about 135 F. That lower temperature does not meet the USDA/FDA recommendation and carries higher risk, especially for young children, pregnant people, older adults, and anyone immunocompromised.', '["sear"]', '[]', 'null', '[{"component_id":"sauce","name":"cherry pan sauce","made_in_recipe":true,"store_bought":false,"ingredients":["cherries","shallot","red wine vinegar","red wine","honey","thyme"]}]', 'published', 'draft', 'global', NULL, '4e4848ebe21c0da57569e1d28a3f86497ff6f0076ef1858bb42e3fcd0abc6f68', 'flavorweave-catalog-package', 'catalog/seared-duck-breast-cherry/v2.json', '2026-10-04T00:00:00.000Z', 'involved', 'standard', '66a97cd2f60ec8784b979b25d5a0627d6bd9f3733e5319e7862835bd2d685c4d');
INSERT OR IGNORE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at, effort_level, ingredient_complexity, classification_hash) VALUES ('rv_seared-scallops-parsnip-puree_v2', 'rcp_seared-scallops-parsnip-puree', 'seared-scallops-parsnip-puree', 2, 'Seared Scallops with Parsnip Purée and Crispy Sage', 'Golden-crusted sea scallops on a silky, sweet parsnip purée, spooned with nutty sage brown butter and crisp-fried sage leaves, with a lemony baby arugula salad for brightness.', 4, 10, 41, 51, 'Medium to bring the parsnips to a bare simmer, then gentle; medium for the brown butter; high, very hot skillet for searing; lowest heat to hold the purée.', 'Parsnips very tender; purée completely silky. Sage crisp and butter nutty brown, not black. Scallops with a deep golden-brown crust, opaque and firm throughout (FDA shellfish). Optional traditional preparation: scallops with a translucent center, about 120 F to 125 F. That lower temperature does not meet the USDA/FDA recommendation and carries higher risk, especially for young children, pregnant people, older adults, and anyone immunocompromised. kitchen_tested is false.', '[]', '[]', 'null', '[{"component_id":"parsnip-puree","name":"silky parsnip purée","made_in_recipe":true,"store_bought":false,"ingredients":["parsnips","whole milk","water","unsalted butter","kosher salt"]},{"component_id":"sage-brown-butter","name":"sage brown butter with crispy sage","made_in_recipe":true,"store_bought":false,"ingredients":["unsalted butter","fresh sage","kosher salt"]},{"component_id":"seared-scallops","name":"seared sea scallops","made_in_recipe":true,"store_bought":false,"ingredients":["sea scallops","neutral oil","kosher salt","black pepper"]},{"component_id":"lemony-arugula","name":"lemony arugula salad","made_in_recipe":true,"store_bought":false,"ingredients":["baby arugula","extra-virgin olive oil","lemon","kosher salt"]}]', 'published', 'draft', 'global', NULL, '0777d2f56df945a784ca980fed9a6d14241624b9321e761a3394d29053414cd1', 'flavorweave-catalog-package', 'catalog/seared-scallops-parsnip-puree/v2.json', '2026-10-04T00:00:00.000Z', 'involved', 'standard', '66a97cd2f60ec8784b979b25d5a0627d6bd9f3733e5319e7862835bd2d685c4d');
INSERT OR IGNORE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at, effort_level, ingredient_complexity, classification_hash) VALUES ('rv_sesame-soba-noodle-bowl_v3', 'rcp_sesame-soba-noodle-bowl', 'sesame-soba-noodle-bowl', 3, 'Sesame Soba Noodle Bowl', 'Cold soba with sesame oil, rice vinegar, soy, and a measured salt in the dressing.', 4, 15, 10, 25, 'Stovetop.', 'Soba tender, not mushy, rinsed cold. Dressing clinging, not pooled.', '["stovetop"]', '[]', 'null', '[]', 'published', 'draft', 'global', NULL, 'd3f83a4579fd4627cabd0cca508562a32d3977ec9e69dfa4ca1cb24be3b3ae69', 'flavorweave-legacy-audit-draft', 'catalog/sesame-soba-noodle-bowl/v3.json', '2026-10-04T00:00:00.000Z', 'easy', 'simple', 'babd7dabd7743db6960cd85230f4a7cab0c70b57bc8930feeaf69b78e19cca59');
INSERT OR IGNORE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at, effort_level, ingredient_complexity, classification_hash) VALUES ('rv_sheet-pan-lemon-herb-chicken_v3', 'rcp_sheet-pan-lemon-herb-chicken', 'sheet-pan-lemon-herb-chicken', 3, 'Sheet-Pan Lemon Herb Chicken', 'Sheet-pan chicken thighs with potatoes, green beans, lemon, garlic, oregano, and thyme.', 4, 15, 40, 55, 'Oven 425 F.', 'Chicken 165 F in the thickest part, away from the bone. Rest 5 minutes.', '["oven","sheet-pan"]', '[]', 'null', '[]', 'published', 'draft', 'global', NULL, 'b1e221021f97dd9560dde80a6d52fd1efe1fab5436cd52aaa6705a39cd7df6ee', 'flavorweave-legacy-catalog-package', 'catalog/sheet-pan-lemon-herb-chicken/v3.json', '2026-10-04T00:00:00.000Z', 'easy', 'simple', 'babd7dabd7743db6960cd85230f4a7cab0c70b57bc8930feeaf69b78e19cca59');
INSERT OR IGNORE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at, effort_level, ingredient_complexity, classification_hash) VALUES ('rv_smoky-lentil-sweet-potato-stew_v3', 'rcp_smoky-lentil-sweet-potato-stew', 'smoky-lentil-sweet-potato-stew', 3, 'Smoky Lentil Sweet Potato Stew', 'Red lentils and sweet potato in a smoky tomato broth, with onion and garlic sweated first.', 4, 15, 30, 45, 'Stovetop.', 'Sweet potato tender, lentils broken down, stew thick enough to hold a spoon.', '["stovetop"]', '["plant","dairy-free"]', 'null', '[]', 'published', 'draft', 'global', NULL, 'a01c99993ceeb9620922bc70f946e4ee9568033505c48695f5043850d2aee29c', 'flavorweave-legacy-catalog-package', 'catalog/smoky-lentil-sweet-potato-stew/v3.json', '2026-10-04T00:00:00.000Z', 'easy', 'simple', 'babd7dabd7743db6960cd85230f4a7cab0c70b57bc8930feeaf69b78e19cca59');
INSERT OR IGNORE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at, effort_level, ingredient_complexity, classification_hash) VALUES ('rv_spanish-potato-tortilla_v2', 'rcp_spanish-potato-tortilla', 'spanish-potato-tortilla', 2, 'Spanish Potato Tortilla', 'Yukon Gold potatoes and onion shallow-fried in olive oil, folded into egg, and set in a skillet. No cheese and no chorizo.', 4, 15, 30, 45, 'Medium for the potatoes, then medium-low to set the eggs. No oven.', 'Potatoes tender, not browned hard. Tortilla set at the edge, the center just firm, not dry. A knife comes out with a moist crumb.', '["shallow-fry"]', '[]', 'null', '[]', 'published', 'draft', 'global', NULL, 'abbee5bfc2575c77d052d60289f4510015d05b2963c61e614aef0bd011430293', 'flavorweave-catalog-package', 'catalog/spanish-potato-tortilla/v2.json', '2026-10-04T00:00:00.000Z', 'involved', 'simple', '5c96a847dece17be968649c3c11b24bd711058ea1c1d8e24db468d59544c5b1f');
INSERT OR IGNORE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at, effort_level, ingredient_complexity, classification_hash) VALUES ('rv_steak-au-poivre-smashed-potatoes_v2', 'rcp_steak-au-poivre-smashed-potatoes', 'steak-au-poivre-smashed-potatoes', 2, 'Steak au Poivre with Crispy Smashed Potatoes', 'Strip steaks pressed into cracked black peppercorns, seared to a dark crust, and finished with a classic French pan sauce of shallot, brandy, Dijon, and cream. Served with baby potatoes boiled, smashed, and oven-roasted until crispy.', 4, 10, 49, 59, 'Oven preheated to 450 F for the potatoes. High heat cast iron for the steaks; medium for the sauce.', 'Whole-muscle beef steaks to 145 F in the center, then a 3-minute rest (FDA). Potatoes tender, then crisp at the edges.', '["boil","roast","sear"]', '[]', 'null', '[{"component_id":"steak","name":"peppercorn-crusted strip steaks with pan sauce","made_in_recipe":true,"store_bought":false,"ingredients":["strip steaks","black peppercorns","shallot","brandy","Dijon","cream","butter","salt","oil"]},{"component_id":"potatoes","name":"crispy smashed potatoes","made_in_recipe":true,"store_bought":false,"ingredients":["baby potatoes","water","olive oil","salt","chives"]}]', 'published', 'draft', 'global', NULL, '7ab834c584eb9b02a85543c5db3956bb62be1507f7ef832c08b708fa1cdccc87', 'flavorweave-catalog-package', 'catalog/steak-au-poivre-smashed-potatoes/v2.json', '2026-10-04T00:00:00.000Z', 'moderate', 'standard', '08ceede8e31d0536861737ed10ce02ecde3d242f006e7c41e7d6c307f16cc5ec');
INSERT OR IGNORE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at, effort_level, ingredient_complexity, classification_hash) VALUES ('rv_tex-mex-steak-fajitas_v2', 'rcp_tex-mex-steak-fajitas', 'tex-mex-steak-fajitas', 2, 'Tex-Mex Skirt Steak Fajitas with Peppers, Onions, and Pico de Gallo', 'Skirt steak marinated in lime juice, garlic, cumin, and chili powder, seared hard in cast iron and sliced across the grain, served with charred bell peppers and onion, warm flour tortillas, fresh pico de gallo of tomato, onion, jalapeno, and cilantro, avocado, and sour cream.', 4, 20, 34, 54, '12-inch cast-iron skillet over high.', 'Steak deeply browned outside and 145 F in the center, then a 5-minute rest (USDA whole-muscle beef); peppers charred at the edges but still crisp-tender. Optional traditional preparation: medium-rare, 130 F to 135 F. That lower temperature does not meet the USDA/FDA recommendation and carries higher risk, especially for young children, pregnant people, older adults, and anyone immunocompromised.', '["sear","saute","toast"]', '[]', 'null', '[{"component_id":"steak","name":"steak","made_in_recipe":true,"store_bought":false,"ingredients":["skirt steak","lime juice","garlic","cumin","chili powder","neutral oil","salt"]},{"component_id":"peppers","name":"peppers and onions","made_in_recipe":true,"store_bought":false,"ingredients":["bell peppers","white onion","neutral oil","salt"]},{"component_id":"pico","name":"pico de gallo","made_in_recipe":true,"store_bought":false,"ingredients":["tomatoes","white onion","jalapeno","cilantro","lime juice","salt"]},{"component_id":"serve","name":"tortillas and toppings","made_in_recipe":true,"store_bought":false,"ingredients":["flour tortillas","avocado","sour cream"]}]', 'published', 'draft', 'global', NULL, 'dbf77555d5690e3af328187f8f2bd2674ee7e85261a708e1a0a73d75c2b2a046', 'flavorweave-catalog-package', 'catalog/tex-mex-steak-fajitas/v2.json', '2026-10-04T00:00:00.000Z', 'moderate', 'simple', 'fff648ac7b6240cd1d7f5fe3af9d8fd777f0aa0b0a9735e530ee04a1e367da2d');
INSERT OR IGNORE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at, effort_level, ingredient_complexity, classification_hash) VALUES ('rv_thai-basil-eggplant-stir-fry_v3', 'rcp_thai-basil-eggplant-stir-fry', 'thai-basil-eggplant-stir-fry', 3, 'Thai Basil Eggplant Stir-Fry', 'Japanese eggplant stir-fried with garlic, soy, a little sugar, red pepper flakes, and Thai basil over rice.', 4, 15, 25, 40, 'Stovetop.', 'Eggplant creamy in the center with browned edges. Basil just wilted. Rice tender.', '["stovetop"]', '["plant","dairy-free"]', '{"soy sauce":"Keep wheat-containing soy sauce. Wheat-free tamari would drop the wheat allergen and is not this version.","fish sauce":"Do not substitute fish sauce. It would drop the plant claim and add finfish."}', '[]', 'published', 'unpublished_curator_draft', 'global', NULL, '372449c7c7dd68419ece3f40c6531c60f144fcbeadf8050dd45bf12dc32aa801', 'flavorweave-legacy-catalog-package', 'catalog/thai-basil-eggplant-stir-fry/v3.json', '2026-10-04T00:00:00.000Z', 'moderate', 'standard', '08ceede8e31d0536861737ed10ce02ecde3d242f006e7c41e7d6c307f16cc5ec');
INSERT OR IGNORE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at, effort_level, ingredient_complexity, classification_hash) VALUES ('rv_thai-yum-nua-beef-salad_v2', 'rcp_thai-yum-nua-beef-salad', 'thai-yum-nua-beef-salad', 2, 'Thai Yum Nua: Seared Steak Salad with Lime-Chile Dressing and Jasmine Rice', 'Flank steak seared hard in a cast-iron skillet, rested, sliced thin, and tossed warm with cucumber, cherry tomatoes, shallots, scallions, mint, and cilantro in a sharp lime, fish sauce, garlic, and bird chile dressing, piled over romaine with jasmine rice on the side.', 4, 12, 32, 44, '10- or 12-inch cast-iron skillet over high until smoking for the steak. 2-quart saucepan covered on low for the rice.', 'Steak deeply browned outside and 145 F at the thickest point, then a 5-minute rest (USDA whole-muscle beef). Vegetables raw and crisp; herbs fresh, not wilted. Rice tender. Optional traditional preparation: medium-rare, about 130 F. That lower temperature does not meet the USDA/FDA recommendation and carries higher risk, especially for young children, pregnant people, older adults, and anyone immunocompromised.', '["sear"]', '[]', 'null', '[{"component_id":"steak","name":"seared flank steak","made_in_recipe":true,"store_bought":false,"ingredients":["flank steak","salt","black pepper","neutral oil"]},{"component_id":"dressing","name":"lime-chile dressing","made_in_recipe":true,"store_bought":false,"ingredients":["lime","fish sauce","brown sugar","bird chiles","garlic"]},{"component_id":"salad","name":"herb salad","made_in_recipe":true,"store_bought":false,"ingredients":["cucumber","cherry tomatoes","shallots","scallions","mint","cilantro","romaine"]},{"component_id":"rice","name":"jasmine rice","made_in_recipe":true,"store_bought":false,"ingredients":["jasmine rice","water","salt"]}]', 'published', 'draft', 'global', NULL, '5e3d2b220edb17336c30fa59ce714c51f8763a44515d6371ce43b3537d59042e', 'flavorweave-catalog-package', 'catalog/thai-yum-nua-beef-salad/v2.json', '2026-10-04T00:00:00.000Z', 'moderate', 'standard', '08ceede8e31d0536861737ed10ce02ecde3d242f006e7c41e7d6c307f16cc5ec');
